#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="${WORKSPACE:-/home/kavia/workspace/code-generation/two-player-tic-tac-toe-30439-30448/backend}"
cd "$WORKSPACE"
if [ ! -f package.json ]; then cat >package.json <<'JSON'
{
  "name": "two-player-tic-tac-toe",
  "version": "0.1.0",
  "main": "index.js",
  "scripts": {
    "start": "node index.js",
    "dev": "nodemon index.js",
    "test": "jest --runInBand"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "nodemon": "^2.0.22",
    "jest": "^29.7.0",
    "node-fetch": "^3.4.0"
  }
}
JSON
fi
if [ ! -f index.js ]; then cat >index.js <<'JS'
const express = require('express');
const path = require('path');
const app = express();
const PORT = process.env.PORT || 3000;
const state = { games: {} };
let server;
app.use(express.json());
app.get('/health', (req, res) => res.json({ status: 'ok' }));
app.get('/', (req, res) => res.sendFile(path.join(__dirname, 'public', 'index.html')));
app.post('/game', (req, res) => { const id = Date.now().toString(); state.games[id] = { board: Array(9).fill(null) }; res.json({ id }); });
app.get('/game/:id', (req, res) => { const g = state.games[req.params.id]; return g ? res.json(g) : res.status(404).end(); });
// export for programmatic testing
module.exports = app;
function start() { server = app.listen(PORT, () => console.log(`Server listening on ${PORT}`)); }
function stop(cb){ if(server) server.close(cb); else cb && cb(); }
// graceful shutdown hooks
process.on('SIGTERM', () => { console.log('SIGTERM received, shutting down'); stop(()=>process.exit(0)); });
process.on('SIGINT', () => { console.log('SIGINT received, shutting down'); stop(()=>process.exit(0)); });
if (require.main === module) { start(); }
JS
fi
mkdir -p public
if [ ! -f public/index.html ]; then cat >public/index.html <<'HTML'
<!doctype html>
<html><head><meta charset="utf-8"><title>Two Player Tic Tac Toe</title></head><body><h1>Two Player Tic Tac Toe (placeholder)</h1></body></html>
HTML
fi
if [ ! -f .gitignore ]; then echo -e "node_modules/\n/tmp/*.log" > .gitignore; fi

