if [ ! -f tests/health.test.js ]; then cat >tests/health.test.js <<'JS'
const fetch = require('node-fetch');
let server, addr;
beforeAll(async () => {
  // load exported express app (should export the app object)
  const app = require('../index');
  // start on ephemeral port
  server = app.listen(0);
  const port = server.address().port;
  addr = `http://127.0.0.1:${port}`;
  // poll /health with short backoff, robust to race/port collisions
  const maxAttempts = 50;
  const delay = ms => new Promise(r => setTimeout(r, ms));
  for (let i = 0; i < maxAttempts; i++) {
    try {
      const res = await fetch(`${addr}/health`);
      if (res && res.ok) return;
    } catch (e) {
      // ignore and retry
    }
    // exponential-ish backoff with cap to avoid long fixed sleeps
    await delay(20 + Math.min(200, i * 10));
  }
  throw new Error('health did not respond in time');
});
afterAll(async () => {
  if (server && server.close) await new Promise(r => server.close(r));
});
test('health endpoint responds', async () => {
  const res = await fetch(`${addr}/health`);
  expect(res.ok).toBeTruthy();
});
JS
fi
# Run tests via npm to prefer local jest; if package.json has test script wired to jest this will run.
# Use --no-audit --no-fund per provided script to reduce noise.
npm test --silent --no-audit --no-fund || { echo 'tests failed' >&2; exit 5; }

